import random
from typing import Tuple, Optional

def modinv(a, p):
    """Modular inverse using Fermat's little theorem (p is prime)."""
    return pow(a, p - 2, p)

class Point:
    def __init__(self, x: Optional[int], y: Optional[int], curve: 'EllipticCurve'):
        self.x = x
        self.y = y
        self.curve = curve

    def __eq__(self, other):
        if self.x is None and self.y is None:
            return other.x is None and other.y is None
        return (self.x == other.x) and (self.y == other.y)

    def __neg__(self):
        if self.x is None:
            return self
        return Point(self.x, (-self.y) % self.curve.p, self.curve)

    def is_infinity(self):
        return self.x is None and self.y is None

    def __repr__(self):
        if self.is_infinity():
            return 'Point(INF)'
        return f'Point({self.x}, {self.y})'

class EllipticCurve:
    def __init__(self, a: int, b: int, p: int):
        self.a = a
        self.b = b
        self.p = p
        self.O = Point(None, None, self)  # Point at infinity

    def is_on_curve(self, P: Point) -> bool:
        if P.is_infinity():
            return True
        x, y = P.x, P.y
        return (y * y - (x * x * x + self.a * x + self.b)) % self.p == 0

    def add(self, P: Point, Q: Point) -> Point:
        if P.is_infinity():
            return Q
        if Q.is_infinity():
            return P
        if P.x == Q.x and (P.y != Q.y or P.y == 0):
            return self.O
        if P == Q:
            return self.double(P)
        # Point addition
        lmbda = ((Q.y - P.y) * modinv(Q.x - P.x, self.p)) % self.p
        x_r = (lmbda * lmbda - P.x - Q.x) % self.p
        y_r = (lmbda * (P.x - x_r) - P.y) % self.p
        R = Point(x_r, y_r, self)
        return R

    def double(self, P: Point) -> Point:
        if P.is_infinity():
            return P
        if P.y == 0:
            return self.O
        # Point doubling
        lmbda = ((3 * P.x * P.x + self.a) * modinv(2 * P.y, self.p)) % self.p
        x_r = (lmbda * lmbda - 2 * P.x) % self.p
        y_r = (lmbda * (P.x - x_r) - P.y) % self.p
        R = Point(x_r, y_r, self)
        return R

    def scalar_mult(self, k: int, P: Point) -> Point:
        if k % self.p == 0 or P.is_infinity():
            return self.O
        result = self.O
        addend = P
        while k > 0:
            if k & 1:
                result = self.add(result, addend)
            addend = self.double(addend)
            k >>= 1
        return result


def baby_step_giant_step(curve: EllipticCurve, G: Point, Q: Point, order: int) -> int:
    """Find integer k such that Q = k*G on given curve, using BSGS."""
    m = int(order ** 0.5) + 1
    tbl = {}
    # Baby steps
    cur = curve.O
    for j in range(m):
        tbl[cur.x, cur.y] = j
        cur = curve.add(cur, G)

    # Precompute giant step
    mG = curve.scalar_mult(m, G)
    cur = Q
    for i in range(m):
        key = (cur.x, cur.y)
        if key in tbl:
            return (i * m + tbl[key]) % order
        cur = curve.add(cur, -mG)
    raise ValueError('No log found!')

# === Demo ===
if __name__ == "__main__":
    # SuperCurve parameters
    p = 14753
    a = 1
    b = -1
    n = 7919
    # Pick a base point G (use values from included supercurve.py normally)
    # We will pick random x and try to get a valid y
    def find_curve_point():
        for x in range(1, p):
            ysq = (x*x*x + a*x + b) % p
            for y in range(p):
                if (y*y) % p == ysq:
                    return (x, y)
        raise Exception('No point found!')
    xG, yG = find_curve_point()
    curve = EllipticCurve(a, b, p)
    G = Point(xG, yG, curve)
    assert curve.is_on_curve(G)
    k = random.randint(1, n-1)
    Q = curve.scalar_mult(k, G)
    rk = baby_step_giant_step(curve, G, Q, n)
    print(f"Random k: {k}")
    print(f"Q = k*G: {Q}")
    print(f"Recovered k by BSGS: {rk}")
    print(f"Result: {k == rk}")

